        "body": "Proper storage and upkeep double the service lifespan of building materials. Prevent continuous contact with damp soils or direct sun exposure. For steel, apply zinc chromate anti-rust primers. For wood and textiles, keep moisture parameters below 12% to prevent mold and rot. Periodically inspect joints and apply polymer-based sealants to block weather penetration."
